// CSD_RATIONALE_BEGIN
// Longest-span CSD for symbolic GSM reasoning.
//
// Root cause of attempt 2 failure (0% accuracy, 87.8% syntax):
//   - The AdaptiveConstrainedStep loop closed the span on the FIRST token that
//     satisfies IsCompletePrefix. Since a bare variable name ("n1", "n") is a
//     valid arithmetic expression, every span closed after 1-2 tokens, yielding
//     tiny and incorrect answers (avg 1.37 visible span tokens).
//   - 6/49 spans were opened so late in the budget that they never closed.
//
// Fix: replace the per-token close check with CloseSpanWithinBudget.
//   CloseSpanWithinBudget generates up to `spanBudget` tokens inside the span
//   and closes at the LONGEST prefix that satisfies IsCompletePrefix, not the
//   first. This allows the model to produce a full expression like
//   "int(n * frac_1 * frac_2)" or "n * (mult + 1)" before the span closes.
//
// Strategy:
//   Main loop: UnconstrainedStep outside spans. When RenderedEndsWith detects
//   "<<", reset currentConstrainedOut to [], then immediately call
//   CloseSpanWithinBudget with a per-span budget of 80 steps. This generates
//   the full constrained expression and emits ">>" at the longest valid complete
//   point, all within the remaining step budget.
//   Residual else branch: if CloseSpanWithinBudget left the span open (no
//   completable prefix found within 80 steps), continue with
//   AdaptiveConstrainedStep + CloseConstrainedSpan until the span closes or the
//   global budget runs out.
//
// Task guidance explicitly permits * for multiplication (the model was confused
// about the operator set), and reinforces exact variable names and the
// "The final answer is <<expr>>" output format.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Free branch (UnconstrainedStep, no << detected):
//     insideConstrainedOut stays false; implication vacuously true.
//   Free branch (<< detected):
//     currentConstrainedOut is set to [], which is valid by the method
//     precondition parser.IsValidPrefix([]). CloseSpanWithinBudget's
//     postcondition then guarantees
//       insideOut ==> parser.IsValidPrefix(currentOut),
//     so validity is preserved regardless of whether the span closed or not.
//     If the span closed, insideConstrainedOut == false; vacuously true.
//   Else branch — close path (IsCompletePrefix true):
//     CloseConstrainedSpan sets insideConstrainedOut := false; vacuously true.
//   Else branch — generate path:
//     AdaptiveConstrainedStep returns EOS or a parser-valid extension of
//     currentConstrainedOut. AppendConstrainedToken appends that token to both
//     generated and currentConstrainedOut, preserving IsValidPrefix.
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   Free branch (UnconstrainedStep):
//     Costs exactly 1 step and appends at most 1 non-EOS token (EOS breaks the
//     loop without appending); steps increases by 1. Bound preserved.
//   Free branch (CloseSpanWithinBudget(sb)):
//     sb <= maxSteps - steps_before, so steps_after = steps_before + sb <=
//     maxSteps. By CloseSpanWithinBudget's length postcondition,
//     |generatedOut| <= |generated_before| + sb. Combined with the loop
//     invariant |generated_before| <= |generatedPrefix| + steps_before,
//     |generatedOut| <= |generatedPrefix| + steps_after. Bound preserved.
//   Else branch — close path:
//     CloseConstrainedSpan costs 1 step and appends at most 1 token (">>").
//     steps increases by 1; bound preserved.
//   Else branch — generate path:
//     AdaptiveConstrainedStep costs 1 step (EOS breaks loop without append).
//     AppendConstrainedToken appends exactly 1 token; steps increased by 1.
//     Net: |generated| grows by at most 1, steps grows by 1; bound preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math word problem step by step using the symbolic variable names from the problem. " +
  "You may use *, +, -, /, //, %, (), and int() in expressions. " +
  "Use the exact variable names as they appear in the problem. " +
  "End your response with: The final answer is <<expr>> " +
  "where expr is a complete symbolic arithmetic expression.");

var steps: nat := 0;
var spanBudget: nat := 80;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
      var remainBudget := maxSteps - steps;
      var sb := if remainBudget <= spanBudget then remainBudget else spanBudget;
      if sb > 0 {
        var cg, ci, cc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, sb
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + sb;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    if parser.IsCompletePrefix(currentConstrainedOut) {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

cost := steps;

